CREATE procedure [fusion].[GenerateMarkitMapLineage] as begin SET NOCOUNT, ANSI_PADDING ON; SET ANSI_WARNINGS ON;
-- look for existing intersects subject to source update M set M.[SourceIntersectID] = OI.ID from [fusion].[MarkitLineageMapping] M inner join Asset S on S.ID = M.SourceAssetID inner join Asset O on O.ID = M.ObjectAssetID inner join [IntersectDetail] OI on OI.[Subject] = S.[Object] and OI.SubjectID = S.ObjectID and OI.[Object] = O.[Object] and OI.[ObjectID] = O.[ObjectID];
-- look for existing intersects flipped object to source update M set M.[SourceIntersectID] = OI.ID from [fusion].[MarkitLineageMapping] M inner join Asset S on S.ID = M.SourceAssetID inner join Asset O on O.ID = M.ObjectAssetID inner join [IntersectDetail] OI on OI.[Object] = S.[Object] and OI.ObjectID = S.[ObjectID] and OI.[Subject] = O.[Object] and OI.[SubjectID] = O.[ObjectID] and M.SourceIntersectID is null
-- create any missing intersects for the business lineage insert into [intersect] (IntersectTypeID, [Subject], SubjectID, [Object], ObjectID, CreatedBy, CreatedOn, UpdatedBy, UpdatedOn, [Owner]) select distinct (select top 1 IT.ID from [IntersectType] IT where (IT.[Object] = O.[Type] and IT.[Subject] = S.[Type] and IT.ObjectID = O.TypeID and IT.SubjectID = S.TypeID)) ,S.[Object] ,S.[ObjectID] ,O.[Object] ,O.[ObjectID] ,0,getutcdate(),0,getutcdate(),'MARKIT LINEAGE' from [fusion].[MarkitLineageMapping] M inner join AssetDetail O on O.ID = M.ObjectAssetID inner join AssetDetail S on S.ID = M.SourceAssetID where M.SourceIntersectID is null;
-- do the update we did before adding new intersects again to catch the new ones -- look for existing intersects subject to source update M set M.[SourceIntersectID] = OI.ID from [fusion].[MarkitLineageMapping] M inner join Asset S on S.ID = M.SourceAssetID inner join Asset O on O.ID = M.ObjectAssetID inner join [IntersectDetail] OI on OI.[Subject] = S.[Object] and OI.SubjectID = S.[ObjectID] and OI.[Object] = O.[Object] and OI.[ObjectID] = O.[ObjectID] and M.SourceIntersectID is null;
-- look for target intersects subject - target update M set M.[TargetIntersectID] = OI.ID from [fusion].[MarkitLineageMapping] M inner join Asset T on T.ID = M.TargetAssetID inner join Asset O on O.ID = M.ObjectAssetID inner join [IntersectDetail] OI on OI.[Subject] = T.[Object] and OI.SubjectID = T.[ObjectID] and OI.[Object] = O.[Object] and OI.[ObjectID] = O.[ObjectID]
-- look for target intersects flipped object - target update M set M.[TargetIntersectID] = OI.ID from [fusion].[MarkitLineageMapping] M inner join Asset T on T.ID = M.TargetAssetID inner join Asset O on O.ID = M.ObjectAssetID inner join [IntersectDetail] OI on OI.[Object] = T.[Object] and OI.ObjectID = T.[ObjectID] and OI.[Subject] = O.[Object] and OI.[SubjectID] = O.[ObjectID] and M.TargetIntersectID is null;
-- create any missing intersects for the business lineage insert into [intersect] (IntersectTypeID, [Subject], SubjectID, [Object], ObjectID, CreatedBy, CreatedOn, UpdatedBy, UpdatedOn, [Owner]) select distinct (select top 1 IT.ID from [intersecttype] IT where (IT.[Object] = O.[Type] and IT.[Subject] = T.[Type] and IT.ObjectID = O.TypeID and IT.SubjectID = T.TypeID)) ,T.[Object] ,T.[ObjectID] ,O.[Object] ,O.[ObjectID] ,0,getutcdate(),0,getutcdate(),'MARKIT LINEAGE' from [fusion].[MarkitLineageMapping] M inner join AssetDetail O on O.ID = M.ObjectAssetID inner join AssetDetail T on T.ID = M.TargetAssetID where M.TargetIntersectID is null;
-- update again for the newly created in above insert update M set M.[TargetIntersectID] = OI.ID from [fusion].[MarkitLineageMapping] M inner join Asset T on T.ID = M.TargetAssetID inner join Asset O on O.ID = M.ObjectAssetID inner join [IntersectDetail] OI on OI.[Subject] = T.[Object] and OI.SubjectID = T.[ObjectID] and OI.[Object] = O.[Object] and OI.[ObjectID] = O.[ObjectID] and M.TargetIntersectID is null;
-- output the results into proper tables here print 'Removing any prior generated Markit Lineage map records';
delete from mapruleitemmapitem where [owner] = 'MARKIT LINEAGE';
print 'Inserting new map records';
Declare @MapItemIDList Table(MapItemID int, sourceintersectid int, targetintersectid int); Declare @MapRuleItemIDList Table(MapRuleItemID int, MapID Int);
update T set T.MapItemID = mi.ID from [fusion].[MarkitLineageMapping] T inner join mapitem mi on(T.SourceIntersectID = mi.SourceIntersectID and T.TargetIntersectID = mi.TargetIntersectID and mi.[Owner] = 'MARKIT LINEAGE');
MERGE INTO mapitem mi USING ( select distinct sourceintersectid, targetintersectid FROM [fusion].[MarkitLineageMapping] where (sourceintersectid is not null and targetintersectid is not null) and sourceintersectid != targetintersectid and coalesce(mapitemid, 0) = 0 ) S ON (1 = 0) WHEN NOT MATCHED THEN INSERT (SourceIntersectID, TargetIntersectID, CreatedBy, CreatedOn, UpdatedBy, UpdatedOn, [Owner]) VALUES (S.sourceintersectid, S.targetintersectid, 0, getutcdate(), 0, getutcdate(), 'MARKIT LINEAGE') OUTPUT INSERTED.ID, S.sourceintersectid, S.targetintersectid into @MapItemIDList;
update T set T.mapitemid = MI.MapItemID from [fusion].[MarkitLineageMapping] T inner join @MapItemIDList MI on (MI.SourceIntersectID = T.SourceIntersectID and MI.TargetIntersectID = T.TargetIntersectID)
delete from mapitem where [owner] = 'MARKIT LINEAGE' and id not in (select mapitemid from [fusion].[MarkitLineageMapping]);
update T set T.mapruleitemid = S.id from [fusion].[MarkitLineageData] T inner join [dbo].[mapruleitem] S on (S.[owner] = 'MARKIT LINEAGE' and S.SourceFusionAttributeID = T.SourceFusionAttributeID and S.TargetFusionAttributeID = T.TargetFusionAttributeID);
MERGE INTO mapruleitem mri USING ( select SourceFusionAttributeID, TargetFusionAttributeID, ID from [fusion].[MarkitLineageData] where coalesce(mapruleitemid, 0) = 0 ) S ON (1 = 0) WHEN NOT MATCHED THEN INSERT (SourceFusionAttributeID, TargetFusionAttributeID, CreatedBy, CreatedOn, UpdatedBy, UpdatedOn, [Owner]) VALUES (S.SourceFusionAttributeID, S.TargetFusionAttributeID, 0, getutcdate(), 0, getutcdate(), 'MARKIT LINEAGE') OUTPUT INSERTED.ID, S.ID into @MapRuleItemIDList;
update T set T.MapRuleItemID = MI.MapRuleItemID from [fusion].[MarkitLineageData] T inner join @MapRuleItemIDList MI on (MI.MapID = T.ID);
delete from mapruleitem where [owner] = 'MARKIT LINEAGE' and id not in (select MapRuleItemID from [fusion].[MarkitLineageData]);
insert into mapruleitemmapitem (MapRuleItemID, MapItemID, [Owner]) SELECT distinct M.MapRuleItemID, O.MapItemID , 'MARKIT LINEAGE' FROM [fusion].[MarkitLineageData] M inner join [fusion].[MarkitLineageMapping] O on O.MapID = M.ID where coalesce(M.MapRuleItemID, 0) != 0 and coalesce(O.MapItemID, 0) != 0;
declare @mapruleitemmapitemCount int; select @mapruleitemmapitemCount = count(1) from mapruleitemmapitem where [owner] = 'MARKIT LINEAGE' print 'Inserted [' + cast(@mapruleitemmapitemCount as varchar) + '] mapruleitemmapitem records';
declare @mapruleitemCount int; select @mapruleitemCount = count(1) from mapruleitem where [owner] = 'MARKIT LINEAGE' print 'Inserted [' + cast(@mapruleitemCount as varchar) + '] mapruleitem records';
declare @mapitemCount int; select @mapitemCount = count(1) from mapitem where [owner] = 'MARKIT LINEAGE' print 'Inserted [' + cast(@mapitemCount as varchar) + '] mapitem records';
end go CREATE procedure [fusion].[LoadMarkitMapLineageData] @fusionID int as begin SET NOCOUNT, ANSI_PADDING ON; SET ANSI_WARNINGS ON;
declare @databaseName varchar(100); declare @sourceFieldTypeID int; declare @targetFieldTypeID int; declare @mapFusionAttributeTypeID int = 710; declare @viewColumnFusionAttributeTypeID int = 715;
select @sourceFieldTypeID = id from fieldtype where [object] = 'FusionAttributeType' and [objectid] = @mapFusionAttributeTypeID and name = 'source'; select @targetFieldTypeID = id from fieldtype where [object] = 'FusionAttributeType' and [objectid] = @mapFusionAttributeTypeID and name = 'target';
IF @sourceFieldTypeID IS NULL begin raiserror('ERROR - Cannot find the Markit Fusion Map Source Field. Please make sure the latest markit fusion attribute types have been pushed to this environment', 16, -1); return; end
IF @targetFieldTypeID IS NULL begin raiserror('ERROR - Cannot find the Markit Fusion Map Target Field. Please make sure the latest markit fusion attribute types have been pushed to this environment', 16, -1); return; end
select top 1 @databaseName = substring(sourceid, 0,charindex('.',sourceid)+1) from fusionattribute where fusionid = @fusionID and fusionattributetypeid = 711 and sourceid like '%.%';
if @databaseName is null begin raiserror('ERROR - Cannot determine the database name to strip from markit fusion attribute data', 16, -1); return; end
declare @fusionTypeId int; select @fusionTypeId = FusionTypeID from [dbo].[Fusion] where ID = @fusionID; if @fusionTypeId != 13 begin raiserror('ERROR - The fusion lineage generation process may only be run for the Markit Fusion Type', 16, -1); return; end
if not exists( select 1 from fusionattribute where fusionid = @fusionID and fusionattributetypeid = @mapFusionAttributeTypeID ) begin raiserror('ERROR - No Markit Fusion Map records exist for the specified Fusion ID', 16, -1); return; end
declare @fusionName nvarchar(250); select @fusionName = name from [dbo].[fusion] where id = @fusionID;
begin print 'Running For Fusion:' + @fusionName; print 'Using Target Field ID:' + cast(@targetFieldTypeID as varchar(100)); print 'Using Source Field ID:' + cast(@sourceFieldTypeID as varchar(100)); print 'Using Database prefix:' + @databaseName; end
declare @viewTableIntersectTypeId int; select @viewTableIntersectTypeId = id from intersecttype where [object] = 'FusionAttributeType' and [Subject] = 'FusionAttributeType' and [subjectid] = 714 and [objectid] = 712 if @viewTableIntersectTypeId is null begin raiserror('ERROR - Cannot identify the intersecttypeid for markit view/table relations', 16, -1); return; end
declare @viewViewIntersectTypeId int; select @viewViewIntersectTypeId = id from intersecttype where [object] = 'FusionAttributeType' and [Subject] = 'FusionAttributeType' and [subjectid] = 714 and [objectid] = 714 if @viewViewIntersectTypeId is null begin raiserror('ERROR - Cannot identify the intersecttypeid for markit view/view relations', 16, -1); return; end
IF OBJECT_ID('tempdb..#maps') IS NOT NULL DROP TABLE #maps;
create table #maps ( ID int identity primary key, MapRuleItemID int, [ParentID] int, [UltimateParentID] int, [Level] int, SourceFusionAttributeID int, SourceFusionAttributeTypeID int, SourceObject nvarchar(500), SourceParentObject nvarchar(max), SourceParentObjectFusionAttributeID int, SourceParentObjectFusionAttributeTypeID int, TargetFusionAttributeID int, TargetFusionAttributeTypeID int, TargetObject nvarchar(500), TargetParentObject nvarchar(max), TargetParentObjectFusionAttributeID int, TargetParentObjectFusionAttributeTypeID int, SourceAssetID bigint, TargetAssetID bigint );
CREATE NONCLUSTERED INDEX [CIX_TempMaps] ON #maps ( SourceFusionAttributeID ASC, TargetFusionAttributeID ASC );
insert into #maps (SourceObject, TargetObject) select distinct replace(cast(F_source.formattedValue as nvarchar(500)), @databaseName, '') as SourceObject , replace(cast(F_target.formattedValue as nvarchar(500)), @databaseName, '') as TargetObject from FusionAttribute FA inner join Field F_source on F_source.ObjectType = 'FusionAttribute' and F_source.ObjectID = FA.ID and F_source.FieldTypeID = @sourceFieldTypeID inner join Field F_target on F_target.ObjectType = 'FusionAttribute' and F_target.ObjectID = FA.ID and F_target.FieldTypeID = @targetFieldTypeID where FA.FusionID = @fusionID and FA.FusionAttributeTypeID = @mapFusionAttributeTypeID
declare @mapRecordCount int; select @mapRecordCount = count(1) from #maps if @fusionTypeId > 0 begin print 'Loaded [' + cast(@mapRecordCount as varchar) + '] map records'; end else begin raiserror('ERROR - Could not load any map records this is most likely because there are no corresponding fusionattributes for the markit source/target mappings.', 16, -1); return; end
update T set T.SourceFusionAttributeID = S.ID, T.SourceFusionAttributeTypeID = S.FusionAttributeTypeID from #maps T inner join fusionattribute S on (S.TextPath = T.SourceObject and S.FusionID = @fusionID)
update T set T.TargetFusionAttributeID = S.ID, T.TargetFusionAttributeTypeID = S.FusionAttributeTypeID from #maps T inner join fusionattribute S on (S.TextPath = T.TargetObject and S.FusionID = @fusionID)
delete from #maps where SourceFusionAttributeID is null or TargetFusionAttributeID is null
update T set T.SourceParentObject = FA_p.TextPath, T.SourceParentObjectFusionAttributeID = FA_p.ID, T.SourceParentObjectFusionAttributeTypeID = FA_p.FusionAttributeTypeID from #maps T inner join fusionattribute FA on (FA.ID = T.SourceFusionAttributeID) inner join fusionattribute FA_p on (FA_p.ID = FA.ParentID)
update T set T.TargetParentObject = FA_p.TextPath, T.TargetParentObjectFusionAttributeID = FA_p.ID, T.TargetParentObjectFusionAttributeTypeID = FA_p.FusionAttributeTypeID from #maps T inner join fusionattribute FA on (FA.ID = T.TargetFusionAttributeID) inner join fusionattribute FA_p on (FA_p.ID = FA.ParentID)
delete from #maps where SourceFusionAttributeID = TargetFusionAttributeID;
insert into #maps (SourceFusionAttributeID, SourceFusionAttributeTypeID, SourceObject, SourceParentObjectFusionAttributeID, SourceParentObject, SourceParentObjectFusionAttributeTypeID, TargetFusionAttributeID, TargetFusionAttributeTypeID, TargetObject, TargetParentObjectFusionAttributeID, TargetParentObject, TargetParentObjectFusionAttributeTypeID) select distinct m.TargetFusionAttributeID as SourceFusionAttributeID, m.TargetFusionAttributeTypeID as SourceFusionAttributeTypeID, m.TargetObject as SourceObject, m.TargetParentObjectFusionAttributeID as SourceParentObjectFusionAttributeID, m.TargetParentObject as SourceParentObject, m.TargetParentObjectFusionAttributeTypeID as SourceParentObjectFusionAttributeTypeID, T.id as TargetFusionAttributeID, T.fusionattributetypeid as TargetFusionAttributeTypeID, T.textpath as TargetObject, i.objectid as TargetParentObjectFusionAttributeID, T_p.name as TargetParentObject, T_p.fusionattributetypeid as TargetParentObjectFusionAttributeTypeID from #maps m inner join [intersect] i on (i.subjectid = m.TargetParentObjectFusionAttributeID and i.[subject] = 'FusionAttribute') inner join fusionattribute T_p on (T_p.id = i.objectid) inner join fusionattribute T on(T.parentid = T_p.id and T.Textpath = T_p.TextPath + replace(m.TargetObject,m.TargetParentObject,'')) where m.TargetFusionAttributeTypeID = @viewColumnFusionAttributeTypeID and i.intersecttypeid = @viewTableIntersectTypeId and m.id not in(select m_2.id from #maps m_2 where (m_2.SourceFusionAttributeID = m.TargetFusionAttributeID and m_2.TargetFusionAttributeID = T.Id) or (m_2.TargetFusionAttributeID = m.TargetFusionAttributeID and m_2.SourceFusionAttributeID = T.id))
insert into #maps (TargetFusionAttributeID, TargetFusionAttributeTypeID, TargetObject, TargetParentObjectFusionAttributeID, TargetParentObject, TargetParentObjectFusionAttributeTypeID, SourceFusionAttributeID, SourceFusionAttributeTypeID, SourceObject, SourceParentObjectFusionAttributeID, SourceParentObject, SourceParentObjectFusionAttributeTypeID) select distinct m.SourceFusionAttributeID as TargetFusionAttributeID, m.SourceFusionAttributeTypeID as TargetFusionAttributeTypeID, m.SourceObject as TargetObject, m.SourceParentObjectFusionAttributeID as TargetParentObjectFusionAttributeID, m.SourceParentObject as TargetParentObject, m.SourceParentObjectFusionAttributeTypeID as TargetParentObjectFusionAttributeTypeID, T.id as SourceFusionAttributeID, T.fusionattributetypeid as SourceFusionAttributeTypeID, T.textpath as SourceObject, i.objectid as SourceParentObjectFusionAttributeID, T_p.name as SourceParentObject, T_p.fusionattributetypeid as SourceParentObjectFusionAttributeTypeID from #maps m inner join [intersect] i on (i.subjectid = m.SourceParentObjectFusionAttributeID and i.[subject] = 'FusionAttribute') inner join fusionattribute T_p on (T_p.id = i.objectid) inner join fusionattribute T on(T.parentid = T_p.id and T.Textpath = T_p.TextPath + replace(m.SourceObject,m.SourceParentObject,'')) where m.SourceFusionAttributeTypeID = @viewColumnFusionAttributeTypeID and i.intersecttypeid = @viewTableIntersectTypeId and m.id not in(select m_2.id from #maps m_2 where (m_2.SourceFusionAttributeID = T.Id and m_2.TargetFusionAttributeID = m.SourceFusionAttributeID) or (m_2.TargetFusionAttributeID = T.id and m_2.SourceFusionAttributeID = m.SourceFusionAttributeID))
insert into #maps (SourceFusionAttributeID, SourceFusionAttributeTypeID, SourceObject, SourceParentObjectFusionAttributeID, SourceParentObject, SourceParentObjectFusionAttributeTypeID, TargetFusionAttributeID, TargetFusionAttributeTypeID, TargetObject, TargetParentObjectFusionAttributeID, TargetParentObject, TargetParentObjectFusionAttributeTypeID) select distinct m.TargetFusionAttributeID as SourceFusionAttributeID, m.TargetFusionAttributeTypeID as SourceFusionAttributeTypeID, m.TargetObject as SourceObject, m.TargetParentObjectFusionAttributeID as SourceParentObjectFusionAttributeID, m.TargetParentObject as SourceParentObject, m.TargetParentObjectFusionAttributeTypeID as SourceParentObjectFusionAttributeTypeID, T.id as TargetFusionAttributeID, T.fusionattributetypeid as TargetFusionAttributeTypeID, T.textpath as TargetObject, i.objectid as TargetParentObjectFusionAttributeID, T_p.name as TargetParentObject, T_p.fusionattributetypeid as TargetParentObjectFusionAttributeTypeID from #maps m inner join [intersect] i on (i.objectid = m.TargetParentObjectFusionAttributeID and i.[object] = 'FusionAttribute') inner join fusionattribute T_p on (T_p.id = i.subjectid) inner join fusionattribute T on(T.FusionId = @fusionId and T.deleted = 0 and T.parentid = T_p.id and T.Textpath = T_p.TextPath + replace(m.TargetObject,m.TargetParentObject,'')) where m.TargetFusionAttributeTypeID = @viewColumnFusionAttributeTypeID and i.intersecttypeid = @viewViewIntersectTypeId and m.id not in(select m_2.id from #maps m_2 where (m_2.SourceFusionAttributeID = m.TargetFusionAttributeID and m_2.TargetFusionAttributeID = T.Id) or (m_2.TargetFusionAttributeID = m.TargetFusionAttributeID and m_2.SourceFusionAttributeID = T.id))
insert into #maps (TargetFusionAttributeID, TargetFusionAttributeTypeID, TargetObject, TargetParentObjectFusionAttributeID, TargetParentObject, TargetParentObjectFusionAttributeTypeID, SourceFusionAttributeID, SourceFusionAttributeTypeID, SourceObject, SourceParentObjectFusionAttributeID, SourceParentObject, SourceParentObjectFusionAttributeTypeID) select distinct m.SourceFusionAttributeID as TargetFusionAttributeID, m.SourceFusionAttributeTypeID as TargetFusionAttributeTypeID, m.SourceObject as TargetObject, m.SourceParentObjectFusionAttributeID as TargetParentObjectFusionAttributeID, m.SourceParentObject as TargetParentObject, m.SourceParentObjectFusionAttributeTypeID as TargetParentObjectFusionAttributeTypeID, T.id as SourceFusionAttributeID, T.fusionattributetypeid as SourceFusionAttributeTypeID, T.textpath as SourceObject, i.objectid as SourceParentObjectFusionAttributeID, T_p.name as SourceParentObject, T_p.fusionattributetypeid as SourceParentObjectFusionAttributeTypeID from #maps m inner join [intersect] i on (i.subjectid = m.SourceParentObjectFusionAttributeID and i.[subject] = 'FusionAttribute') inner join fusionattribute T_p on (T_p.id = i.objectid) inner join fusionattribute T on(T.FusionId = @fusionId and T.deleted = 0 and T.parentid = T_p.id and T.Textpath = T_p.TextPath + replace(m.SourceObject,m.SourceParentObject,'')) where m.SourceFusionAttributeTypeID = @viewColumnFusionAttributeTypeID and i.intersecttypeid = @viewViewIntersectTypeId and m.id not in(select m_2.id from #maps m_2 where (m_2.SourceFusionAttributeID = T.Id and m_2.TargetFusionAttributeID = m.SourceFusionAttributeID) or (m_2.TargetFusionAttributeID = T.id and m_2.SourceFusionAttributeID = m.SourceFusionAttributeID))
IF OBJECT_ID('tempdb..#objectmap') IS NOT NULL DROP TABLE #objectmap;
create table #objectmap ( FusionAttributeID int, ObjectAssetID bigint )
CREATE NONCLUSTERED INDEX [CIX_TempObjectMap] ON #objectmap ( FusionAttributeID ASC, ObjectAssetID ASC );
-- find fusion attributes related to business glossary items insert into #objectMap (FusionAttributeID, ObjectAssetID) select distinct M.FusionAttributeID, A.ID as ObjectAssetID from ( select SourceFusionAttributeID as FusionAttributeID from #maps union all select TargetFusionAttributeID as FusionAttributeID from #maps ) M inner join [IntersectDetail] OI on OI.[Subject] <> 'FusionAttribute' and OI.[Object] = 'FusionAttribute' and OI.ObjectID = M.FusionAttributeID and OI.PredicateType = 8 inner join Asset A on A.[Object] = OI.[Subject] and A.ObjectID = OI.SubjectID
update T set T.sourceAssetId = A.ID from #maps T inner join [IntersectDetail] OI on OI.Subject <> 'FusionAttribute' and OI.Object = 'FusionAttribute' and OI.ObjectID = T.SourceParentObjectFusionAttributeID and OI.PredicateType = 8 inner join Asset A on A.[object] = OI.[subject] and A.ObjectID = OI.subjectid
update T set T.targetAssetId = A.ID from #maps T inner join [IntersectDetail] OI on OI.Subject <> 'FusionAttribute' and OI.Object = 'FusionAttribute' and OI.ObjectID = T.TargetParentObjectFusionAttributeID and OI.PredicateType = 8 inner join Asset A on A.[object] = OI.subject and A.ObjectID = OI.subjectID
-- save the map records off to the markit lineage table with updated update date truncate table [fusion].MarkitLineageData truncate table [fusion].MarkitLineageMapToBusinessItems
insert into [fusion].MarkitLineageData (MapRuleItemID,[ParentID],[UltimateParentID],[Level],SourceFusionAttributeID,SourceFusionAttributeTypeID,SourceObject, SourceParentObject,SourceParentObjectFusionAttributeID,SourceParentObjectFusionAttributeTypeID,TargetFusionAttributeID, TargetFusionAttributeTypeID,TargetObject,TargetParentObject,TargetParentObjectFusionAttributeID,TargetParentObjectFusionAttributeTypeID, UpdatedOn,SourceAssetId,TargetAssetId) select MapRuleItemID, [ParentID], [UltimateParentID], [Level], SourceFusionAttributeID, SourceFusionAttributeTypeID, SourceObject, SourceParentObject, SourceParentObjectFusionAttributeID, SourceParentObjectFusionAttributeTypeID, TargetFusionAttributeID, TargetFusionAttributeTypeID, TargetObject, TargetParentObject, TargetParentObjectFusionAttributeID, TargetParentObjectFusionAttributeTypeID, getutcdate() as UpdatedOn, SourceAssetId, TargetAssetId from #maps;
insert into [fusion].MarkitLineageMapToBusinessItems (FusionAttributeID, ObjectAssetID) select FusionAttributeID, ObjectAssetID from #objectmap;
print 'Saved results to temporary table for webjob processing' end go ALTER procedure [fusion].[GenerateMarkitMapLineageData] @fusionID int, @useNewMethod bit = 0 as begin SET NOCOUNT, ANSI_PADDING ON; SET ANSI_WARNINGS ON;
if (@useNewMethod = 1) begin exec [fusion].[LoadMarkitMapLineageData] @fusionID return; end
declare @databaseName varchar(100); declare @sourceFieldTypeID int; declare @targetFieldTypeID int; declare @mapFusionAttributeTypeID int = 710; declare @viewColumnFusionAttributeTypeID int = 715;
select @sourceFieldTypeID = id from fieldtype where [object] = 'FusionAttributeType' and [objectid] = @mapFusionAttributeTypeID and name = 'source'; select @targetFieldTypeID = id from fieldtype where [object] = 'FusionAttributeType' and [objectid] = @mapFusionAttributeTypeID and name = 'target';
IF @sourceFieldTypeID IS NULL begin raiserror('ERROR - Cannot find the Markit Fusion Map Source Field. Please make sure the latest markit fusion attribute types have been pushed to this environment', 16, -1); return; end
IF @targetFieldTypeID IS NULL begin raiserror('ERROR - Cannot find the Markit Fusion Map Target Field. Please make sure the latest markit fusion attribute types have been pushed to this environment', 16, -1); return; end
select top 1 @databaseName = substring(sourceid, 0,charindex('.',sourceid)+1) from fusionattribute where fusionid = @fusionID and fusionattributetypeid = 711 and sourceid like '%.%';
if @databaseName is null begin raiserror('ERROR - Cannot determine the database name to strip from markit fusion attribute data', 16, -1); return; end
declare @fusionTypeId int; select @fusionTypeId = FusionTypeID from [dbo].[Fusion] where ID = @fusionID; if @fusionTypeId != 13 begin raiserror('ERROR - The fusion lineage generation process may only be run for the Markit Fusion Type', 16, -1); return; end
if not exists( select 1 from fusionattribute where fusionid = @fusionID and fusionattributetypeid = @mapFusionAttributeTypeID ) begin raiserror('ERROR - No Markit Fusion Map records exist for the specified Fusion ID', 16, -1); return; end
declare @fusionName nvarchar(250); select @fusionName = name from [dbo].[fusion] where id = @fusionID;
begin print 'Running For Fusion:' + @fusionName; print 'Using Target Field ID:' + cast(@targetFieldTypeID as varchar(100)); print 'Using Source Field ID:' + cast(@sourceFieldTypeID as varchar(100)); print 'Using Database prefix:' + @databaseName; end
declare @viewTableIntersectTypeId int; select @viewTableIntersectTypeId = id from intersecttype where [object] = 'FusionAttributeType' and [Subject] = 'FusionAttributeType' and [subjectid] = 714 and [objectid] = 712 if @viewTableIntersectTypeId is null begin raiserror('ERROR - Cannot identify the intersecttypeid for markit view/table relations', 16, -1); return; end
declare @viewViewIntersectTypeId int; select @viewViewIntersectTypeId = id from intersecttype where [object] = 'FusionAttributeType' and [Subject] = 'FusionAttributeType' and [subjectid] = 714 and [objectid] = 714 if @viewViewIntersectTypeId is null begin raiserror('ERROR - Cannot identify the intersecttypeid for markit view/view relations', 16, -1); return; end
IF OBJECT_ID('tempdb..#maps') IS NOT NULL DROP TABLE #maps;
create table #maps ( ID int identity primary key, MapRuleItemID int, [ParentID] int, [UltimateParentID] int, [Level] int, SourceFusionAttributeID int, SourceFusionAttributeTypeID int, SourceObject nvarchar(500), SourceParentObject nvarchar(max), SourceParentObjectFusionAttributeID int, SourceParentObjectFusionAttributeTypeID int, TargetFusionAttributeID int, TargetFusionAttributeTypeID int, TargetObject nvarchar(500), TargetParentObject nvarchar(max), TargetParentObjectFusionAttributeID int, TargetParentObjectFusionAttributeTypeID int, [Source] varchar(50), [SourceID] int, [Target] varchar(50), [TargetID] int, );
CREATE NONCLUSTERED INDEX [CIX_TempMaps] ON #maps ( SourceFusionAttributeID ASC, TargetFusionAttributeID ASC );
IF OBJECT_ID('tempdb..#objectmap') IS NOT NULL DROP TABLE #objectmap;
create table #objectmap ( MapID int, MapItemID int, [Object] varchar(50), [ObjectID] int, [SourceIntersectID] int, [TargetIntersectID] int )
CREATE NONCLUSTERED INDEX [CIX_TempObjectMap] ON #objectmap ( MapID ASC, [Object] ASC, [ObjectID] ASC );
insert into #maps (SourceObject, TargetObject) select distinct replace(cast(F_source.formattedValue as nvarchar(500)), @databaseName, '') as SourceObject , replace(cast(F_target.formattedValue as nvarchar(500)), @databaseName, '') as TargetObject from FusionAttribute FA inner join Field F_source on F_source.ObjectType = 'FusionAttribute' and F_source.ObjectID = FA.ID and F_source.FieldTypeID = @sourceFieldTypeID inner join Field F_target on F_target.ObjectType = 'FusionAttribute' and F_target.ObjectID = FA.ID and F_target.FieldTypeID = @targetFieldTypeID where FA.FusionID = @fusionID and FA.FusionAttributeTypeID = @mapFusionAttributeTypeID
declare @mapRecordCount int; select @mapRecordCount = count(1) from #maps if @fusionTypeId > 0 begin print 'Loaded [' + cast(@mapRecordCount as varchar) + '] map records'; end else begin raiserror('ERROR - Could not load any map records this is most likely because there are no corresponding fusionattributes for the markit source/target mappings.', 16, -1); return; end
update T set T.SourceFusionAttributeID = S.ID, T.SourceFusionAttributeTypeID = S.FusionAttributeTypeID from #maps T inner join fusionattribute S on (S.TextPath = T.SourceObject and S.FusionID = @fusionID)
update T set T.TargetFusionAttributeID = S.ID, T.TargetFusionAttributeTypeID = S.FusionAttributeTypeID from #maps T inner join fusionattribute S on (S.TextPath = T.TargetObject and S.FusionID = @fusionID)
delete from #maps where SourceFusionAttributeID is null or TargetFusionAttributeID is null
update T set T.SourceParentObject = FA_p.TextPath, T.SourceParentObjectFusionAttributeID = FA_p.ID, T.SourceParentObjectFusionAttributeTypeID = FA_p.FusionAttributeTypeID from #maps T inner join fusionattribute FA on (FA.ID = T.SourceFusionAttributeID) inner join fusionattribute FA_p on (FA_p.ID = FA.ParentID)
update T set T.TargetParentObject = FA_p.TextPath, T.TargetParentObjectFusionAttributeID = FA_p.ID, T.TargetParentObjectFusionAttributeTypeID = FA_p.FusionAttributeTypeID from #maps T inner join fusionattribute FA on (FA.ID = T.TargetFusionAttributeID) inner join fusionattribute FA_p on (FA_p.ID = FA.ParentID)
delete from #maps where SourceFusionAttributeID = TargetFusionAttributeID;
insert into #maps (SourceFusionAttributeID, SourceFusionAttributeTypeID, SourceObject, SourceParentObjectFusionAttributeID, SourceParentObject, SourceParentObjectFusionAttributeTypeID, TargetFusionAttributeID, TargetFusionAttributeTypeID, TargetObject, TargetParentObjectFusionAttributeID, TargetParentObject, TargetParentObjectFusionAttributeTypeID) select distinct m.TargetFusionAttributeID as SourceFusionAttributeID, m.TargetFusionAttributeTypeID as SourceFusionAttributeTypeID, m.TargetObject as SourceObject, m.TargetParentObjectFusionAttributeID as SourceParentObjectFusionAttributeID, m.TargetParentObject as SourceParentObject, m.TargetParentObjectFusionAttributeTypeID as SourceParentObjectFusionAttributeTypeID, T.id as TargetFusionAttributeID, T.fusionattributetypeid as TargetFusionAttributeTypeID, T.textpath as TargetObject, i.objectid as TargetParentObjectFusionAttributeID, T_p.name as TargetParentObject, T_p.fusionattributetypeid as TargetParentObjectFusionAttributeTypeID from #maps m inner join [intersect] i on (i.subjectid = m.TargetParentObjectFusionAttributeID and i.[subject] = 'FusionAttribute') inner join fusionattribute T_p on (T_p.id = i.objectid) inner join fusionattribute T on(T.parentid = T_p.id and T.Textpath = T_p.TextPath + replace(m.TargetObject,m.TargetParentObject,'')) where m.TargetFusionAttributeTypeID = @viewColumnFusionAttributeTypeID and i.intersecttypeid = @viewTableIntersectTypeId and m.id not in(select m_2.id from #maps m_2 where (m_2.SourceFusionAttributeID = m.TargetFusionAttributeID and m_2.TargetFusionAttributeID = T.Id) or (m_2.TargetFusionAttributeID = m.TargetFusionAttributeID and m_2.SourceFusionAttributeID = T.id))
insert into #maps (TargetFusionAttributeID, TargetFusionAttributeTypeID, TargetObject, TargetParentObjectFusionAttributeID, TargetParentObject, TargetParentObjectFusionAttributeTypeID, SourceFusionAttributeID, SourceFusionAttributeTypeID, SourceObject, SourceParentObjectFusionAttributeID, SourceParentObject, SourceParentObjectFusionAttributeTypeID) select distinct m.SourceFusionAttributeID as TargetFusionAttributeID, m.SourceFusionAttributeTypeID as TargetFusionAttributeTypeID, m.SourceObject as TargetObject, m.SourceParentObjectFusionAttributeID as TargetParentObjectFusionAttributeID, m.SourceParentObject as TargetParentObject, m.SourceParentObjectFusionAttributeTypeID as TargetParentObjectFusionAttributeTypeID, T.id as SourceFusionAttributeID, T.fusionattributetypeid as SourceFusionAttributeTypeID, T.textpath as SourceObject, i.objectid as SourceParentObjectFusionAttributeID, T_p.name as SourceParentObject, T_p.fusionattributetypeid as SourceParentObjectFusionAttributeTypeID from #maps m inner join [intersect] i on (i.subjectid = m.SourceParentObjectFusionAttributeID and i.[subject] = 'FusionAttribute') inner join fusionattribute T_p on (T_p.id = i.objectid) inner join fusionattribute T on(T.parentid = T_p.id and T.Textpath = T_p.TextPath + replace(m.SourceObject,m.SourceParentObject,'')) where m.SourceFusionAttributeTypeID = @viewColumnFusionAttributeTypeID and i.intersecttypeid = @viewTableIntersectTypeId and m.id not in(select m_2.id from #maps m_2 where (m_2.SourceFusionAttributeID = T.Id and m_2.TargetFusionAttributeID = m.SourceFusionAttributeID) or (m_2.TargetFusionAttributeID = T.id and m_2.SourceFusionAttributeID = m.SourceFusionAttributeID))
insert into #maps (SourceFusionAttributeID, SourceFusionAttributeTypeID, SourceObject, SourceParentObjectFusionAttributeID, SourceParentObject, SourceParentObjectFusionAttributeTypeID, TargetFusionAttributeID, TargetFusionAttributeTypeID, TargetObject, TargetParentObjectFusionAttributeID, TargetParentObject, TargetParentObjectFusionAttributeTypeID) select distinct m.TargetFusionAttributeID as SourceFusionAttributeID, m.TargetFusionAttributeTypeID as SourceFusionAttributeTypeID, m.TargetObject as SourceObject, m.TargetParentObjectFusionAttributeID as SourceParentObjectFusionAttributeID, m.TargetParentObject as SourceParentObject, m.TargetParentObjectFusionAttributeTypeID as SourceParentObjectFusionAttributeTypeID, T.id as TargetFusionAttributeID, T.fusionattributetypeid as TargetFusionAttributeTypeID, T.textpath as TargetObject, i.objectid as TargetParentObjectFusionAttributeID, T_p.name as TargetParentObject, T_p.fusionattributetypeid as TargetParentObjectFusionAttributeTypeID from #maps m inner join [intersect] i on (i.objectid = m.TargetParentObjectFusionAttributeID and i.[object] = 'FusionAttribute') inner join fusionattribute T_p on (T_p.id = i.subjectid) inner join fusionattribute T on(T.FusionId = @fusionId and T.deleted = 0 and T.parentid = T_p.id and T.Textpath = T_p.TextPath + replace(m.TargetObject,m.TargetParentObject,'')) where m.TargetFusionAttributeTypeID = @viewColumnFusionAttributeTypeID and i.intersecttypeid = @viewViewIntersectTypeId and m.id not in(select m_2.id from #maps m_2 where (m_2.SourceFusionAttributeID = m.TargetFusionAttributeID and m_2.TargetFusionAttributeID = T.Id) or (m_2.TargetFusionAttributeID = m.TargetFusionAttributeID and m_2.SourceFusionAttributeID = T.id))
insert into #maps (TargetFusionAttributeID, TargetFusionAttributeTypeID, TargetObject, TargetParentObjectFusionAttributeID, TargetParentObject, TargetParentObjectFusionAttributeTypeID, SourceFusionAttributeID, SourceFusionAttributeTypeID, SourceObject, SourceParentObjectFusionAttributeID, SourceParentObject, SourceParentObjectFusionAttributeTypeID) select distinct m.SourceFusionAttributeID as TargetFusionAttributeID, m.SourceFusionAttributeTypeID as TargetFusionAttributeTypeID, m.SourceObject as TargetObject, m.SourceParentObjectFusionAttributeID as TargetParentObjectFusionAttributeID, m.SourceParentObject as TargetParentObject, m.SourceParentObjectFusionAttributeTypeID as TargetParentObjectFusionAttributeTypeID, T.id as SourceFusionAttributeID, T.fusionattributetypeid as SourceFusionAttributeTypeID, T.textpath as SourceObject, i.objectid as SourceParentObjectFusionAttributeID, T_p.name as SourceParentObject, T_p.fusionattributetypeid as SourceParentObjectFusionAttributeTypeID from #maps m inner join [intersect] i on (i.subjectid = m.SourceParentObjectFusionAttributeID and i.[subject] = 'FusionAttribute') inner join fusionattribute T_p on (T_p.id = i.objectid) inner join fusionattribute T on(T.FusionId = @fusionId and T.deleted = 0 and T.parentid = T_p.id and T.Textpath = T_p.TextPath + replace(m.SourceObject,m.SourceParentObject,'')) where m.SourceFusionAttributeTypeID = @viewColumnFusionAttributeTypeID and i.intersecttypeid = @viewViewIntersectTypeId and m.id not in(select m_2.id from #maps m_2 where (m_2.SourceFusionAttributeID = T.Id and m_2.TargetFusionAttributeID = m.SourceFusionAttributeID) or (m_2.TargetFusionAttributeID = T.id and m_2.SourceFusionAttributeID = m.SourceFusionAttributeID))
update m_S set m_S.ParentID = m_T.ID from #maps m_T left outer join #maps m_S on (m_T.TargetFusionAttributeID = m_S.SourceFusionAttributeID)
IF OBJECT_ID('tempdb..#levelMap') IS NOT NULL DROP TABLE #levelMap;
;with C as ( select ID, SourceFusionAttributeID as SourceID, TargetFusionAttributeID as TargetID, ID as [UltimateParentID], 0 as [level] from #maps where ParentID is null union all select T.ID, T.SourceFusionAttributeID as SourceID, T.TargetFusionAttributeID as TargetID, C.[UltimateParentID] as [UltimateParentID], C.[level] + 1 from #maps as T inner join C on T.ParentID = C.ID ) select C.ID, C.[level], C.[UltimateParentID] into #levelMap from C OPTION (MAXRECURSION 25)
update T set T.[level] = S.[level], T.[UltimateParentID] = S.[UltimateParentID] from #maps T inner join #levelMap S on S.ID = T.ID;
insert into #objectmap (MapID, [Object], [ObjectID]) select T.ID, OI.[subject], OI.[subjectid] from #maps T inner join [IntersectDetail] OI on OI.Subject <> 'FusionAttribute' and OI.Object = 'FusionAttribute' and OI.ObjectID in (T.SourceFusionAttributeID, T.TargetFusionAttributeID) and OI.PredicateType = 8
update T set T.[source] = OI.[subject], T.[sourceid] = OI.[subjectid] from #maps T inner join [IntersectDetail] OI on OI.Subject <> 'FusionAttribute' and OI.Object = 'FusionAttribute' and OI.ObjectID = T.SourceParentObjectFusionAttributeID and OI.PredicateType = 8
update T set T.[target] = OI.[subject], T.[targetid] = OI.[subjectid] from #maps T inner join [IntersectDetail] OI on OI.Subject <> 'FusionAttribute' and OI.Object = 'FusionAttribute' and OI.ObjectID = T.TargetParentObjectFusionAttributeID and OI.PredicateType = 8
insert into #objectmap (MapID, [Object], [ObjectID]) select T.ID, SO.[object], SO.[objectID] from #maps T inner join #maps S on T.UltimateParentID = S.UltimateParentID inner join #objectmap SO on S.ID = SO.MapID left join #objectmap T_O on (T.ID = T_O.MapID and T_O.[object] is null);
WITH hierarchy (id, [target], [targetid], [source], [sourceid]) AS ( SELECT id, [target], [targetid], [source], [sourceid] FROM #maps WHERE [parentid] is null
UNION ALL
SELECT mc.id, coalesce(mc.[target], mc.[source], gps.[target]) as [target], coalesce(mc.targetid, mc.sourceid, gps.targetid) as [targetid], coalesce(mc.[source], gps.[target], gps.[source]) as [source], coalesce(mc.sourceid, gps.targetid, gps.sourceid) as [targetid] FROM #maps mc JOIN hierarchy gps ON gps.id = mc.parentid ) UPDATE T set T.[target] = cte.[target], T.[targetid] = cte.[targetid], T.[source] = cte.[source], T.[sourceid] = cte.[sourceid] from #maps T inner join hierarchy cte on cte.id = T.id OPTION (MAXRECURSION 50)
update T set T.[sourceintersectid] = OI.ID from #objectmap T inner join #maps M on (T.MapID = M.ID) inner join [IntersectDetail] OI on OI.[Subject] = M.[Source] and OI.SubjectID = M.[SourceID] and OI.[Object] = T.[Object] and OI.[ObjectID] = T.[ObjectID];
update T set T.[sourceintersectid] = OI.ID from #objectmap T inner join #maps M on (T.MapID = M.ID) inner join [IntersectDetail] OI on OI.[Object] = M.[Source] and OI.ObjectID = M.[SourceID] and OI.[Subject] = T.[Object] and OI.[SubjectID] = T.[ObjectID] and T.sourceintersectid is null
insert into [intersect] (IntersectTypeID, [Subject], SubjectID, [Object], ObjectID, CreatedBy, CreatedOn, UpdatedBy, UpdatedOn, [Owner]) select distinct (select top 1 i_t.ID from [intersecttype] i_t inner join [Predicate] P on I_T.[predicateid] = P.ID where (P.[Type] not in (3,4) and i_t.[object] = c_s.objecttype and i_t.[subject] = c_t.objecttype and i_t.objectid = c_s.objecttypeid and i_t.subjectid = c_t.objecttypeid)) ,T.[Source] ,T.[SourceID] ,OM.[Object] ,OM.[ObjectID] ,0,getutcdate(),0,getutcdate(),'MARKIT LINEAGE' from #maps T inner join #objectmap OM on (T.ID = OM.MapID) inner join [cache].[objectdetails] c_s on (c_s.[object] = OM.[object] and c_s.[objectid] = OM.[objectid]) inner join [cache].[objectdetails] c_t on (c_t.[object] = T.[source] and c_t.[objectid] = T.[sourceid]) where OM.sourceIntersectID is null;
update OM set OM.[sourceintersectid] = OI.ID from #objectmap OM inner join #maps T on (OM.MapID = T.ID) inner join [IntersectDetail] OI on OI.[Subject] = T.[Source] and OI.SubjectID = T.[SourceID] and OI.[Object] = OM.[Object] and OI.[ObjectID] = OM.[ObjectID] and OM.sourceintersectid is null;
update OM set OM.[targetintersectid] = OI.ID from #objectmap OM inner join #maps T on (OM.MapID = T.ID) inner join [IntersectDetail] OI on OI.[Subject] = T.[Target] and OI.SubjectID = T.[TargetID] and OI.[Object] = OM.[Object] and OI.[ObjectID] = OM.[ObjectID]
update OM set OM.[targetintersectid] = OI.ID from #objectmap OM inner join #maps T on (OM.MapID = T.ID) inner join [IntersectDetail] OI on OI.[Object] = T.[Target] and OI.ObjectID = T.[TargetID] and OI.[Subject] = OM.[Object] and OI.[SubjectID] = OM.[ObjectID] and OM.targetintersectid is null;
insert into [intersect] (IntersectTypeID, [Subject], SubjectID, [Object], ObjectID, CreatedBy, CreatedOn, UpdatedBy, UpdatedOn, [Owner]) select distinct (select top 1 i_t.ID from [intersecttype] i_t inner join [Predicate] P on I_T.[predicateid] = P.ID where (P.[Type] not in (3,4) and i_t.[object] = c_s.objecttype and i_t.[subject] = c_t.objecttype and i_t.objectid = c_s.objecttypeid and i_t.subjectid = c_t.objecttypeid)) ,T.[target] ,T.[targetID] ,OM.[Object] ,OM.[ObjectID] ,0,getutcdate(),0,getutcdate(),'MARKIT LINEAGE' from #maps T inner join #objectmap OM on (T.ID = OM.MapID) inner join [cache].[objectdetails] c_s on (c_s.[object] = OM.[object] and c_s.[objectid] = OM.[objectid]) inner join [cache].[objectdetails] c_t on (c_t.[object] = T.[target] and c_t.[objectid] = T.[targetid]) where OM.targetintersectid is null;
update OM set OM.[targetintersectid] = OI.ID from #objectmap OM inner join #maps T on (OM.MapID = T.ID) inner join [IntersectDetail] OI on OI.[Subject] = T.[Target] and OI.SubjectID = T.[TargetID] and OI.[Object] = OM.[Object] and OI.[ObjectID] = OM.[ObjectID] and OM.targetintersectid is null;
print 'Removing any prior generated Markit Lineage map records';
delete from mapruleitemmapitem where [owner] = 'MARKIT LINEAGE';
print 'Inserting new map records';
Declare @MapItemIDList Table(MapItemID int, sourceintersectid int, targetintersectid int); Declare @MapRuleItemIDList Table(MapRuleItemID int, MapID Int);
update T set T.MapItemID = mi.ID from #objectmap T inner join mapitem mi on(T.sourceintersectid = mi.SourceIntersectID and T.targetintersectid = mi.TargetIntersectID and mi.[Owner] = 'MARKIT LINEAGE');
MERGE INTO mapitem mi USING ( select distinct sourceintersectid, targetintersectid FROM #objectmap where (sourceintersectid is not null and targetintersectid is not null) and sourceintersectid != targetintersectid and mapitemid is null ) S ON (1 = 0) WHEN NOT MATCHED THEN INSERT (SourceIntersectID, TargetIntersectID, CreatedBy, CreatedOn, UpdatedBy, UpdatedOn, [Owner]) VALUES (S.sourceintersectid, S.targetintersectid, 0, getutcdate(), 0, getutcdate(), 'MARKIT LINEAGE') OUTPUT INSERTED.ID, S.sourceintersectid, S.targetintersectid into @MapItemIDList;
update T set T.mapitemid = MI.MapItemID from #objectmap T inner join @MapItemIDList MI on (MI.sourceintersectid = T.sourceintersectid and MI.targetintersectid = T.targetintersectid)
delete from mapitem where [owner] = 'MARKIT LINEAGE' and id not in (select mapitemid from #objectmap);
update T set T.mapruleitemid = S.id from #maps T inner join [dbo].[mapruleitem] S on (S.[owner] = 'MARKIT LINEAGE' and S.SourceFusionAttributeID = T.SourceFusionAttributeID and S.TargetFusionAttributeID = T.TargetFusionAttributeID);
MERGE INTO mapruleitem mri USING ( select SourceFusionAttributeID, TargetFusionAttributeID, ID from #maps where mapruleitemid is null ) S ON (1 = 0) WHEN NOT MATCHED THEN INSERT (SourceFusionAttributeID, TargetFusionAttributeID, CreatedBy, CreatedOn, UpdatedBy, UpdatedOn, [Owner]) VALUES (S.SourceFusionAttributeID, S.TargetFusionAttributeID, 0, getutcdate(), 0, getutcdate(), 'MARKIT LINEAGE') OUTPUT INSERTED.ID, S.ID into @MapRuleItemIDList;
update T set T.MapRuleItemID = MI.MapRuleItemID from #maps T inner join @MapRuleItemIDList MI on (MI.MapID = T.ID);
delete from mapruleitem where [owner] = 'MARKIT LINEAGE' and id not in (select MapRuleItemID from #maps);
insert into mapruleitemmapitem (MapRuleItemID, MapItemID, [Owner]) SELECT distinct M.MapRuleItemID, OM.MapItemID , 'MARKIT LINEAGE' FROM #maps M inner join #objectmap OM on(M.ID = OM.MapID) where M.MapRuleItemID is not null and OM.MapItemID is not null;
declare @mapruleitemmapitemCount int; select @mapruleitemmapitemCount = count(1) from mapruleitemmapitem where [owner] = 'MARKIT LINEAGE' print 'Inserted [' + cast(@mapruleitemmapitemCount as varchar) + '] mapruleitemmapitem records';
declare @mapruleitemCount int; select @mapruleitemCount = count(1) from mapruleitem where [owner] = 'MARKIT LINEAGE' print 'Inserted [' + cast(@mapruleitemCount as varchar) + '] mapruleitem records';
declare @mapitemCount int; select @mapitemCount = count(1) from mapitem where [owner] = 'MARKIT LINEAGE' print 'Inserted [' + cast(@mapitemCount as varchar) + '] mapitem records';
end go

